import { languages, codeExamples } from '../data/mockData'

export function generateMockCode(prompt: string, language: string): string {
  const lang = language.toLowerCase()

  if (lang === 'python') {
    return codeExamples.python
  } else if (lang === 'typescript') {
    return codeExamples.typescript
  } else if (lang === 'javascript') {
    return codeExamples.javascript
  }

  // Generic template
  return `// Generated code for: ${prompt}
// Language: ${language}
// Generated by DevAI

function solution() {
  // Implementation based on your requirements
  console.log("DevAI generated solution");
  
  // TODO: Implement your logic here
  const result = processInput();
  return result;
}

function processInput() {
  // Core logic
  return "Hello from DevAI!";
}

solution();`
}

export function generateFixedCode(buggyCode: string, _language: string, error: string): string {
  return `// Fixed code - DevAI debugger
// Error detected: ${error || 'Logic error'}
// Fix applied: Input validation and error handling added

${buggyCode.split('\n').map((line, i) => {
  if (i === 0) return `// FIXED: Added proper error handling\n${line}`
  return line
}).join('\n')}

// Bug fix explanation:
// 1. Added null/undefined checks
// 2. Added proper error handling with try/catch
// 3. Fixed the logic flow`
}

export function generateExplanation(code: string, language: string) {
  const lines = code.split('\n')
  return {
    summary: `This ${language} code implements a utility function with clean, modular design. It follows best practices for readability and maintainability.`,
    complexity: {
      time: 'O(n)',
      space: 'O(1)',
    },
    concepts: [
      'Functional Programming',
      'Error Handling',
      'Type Safety',
      'Code Modularity',
    ],
    lineExplanations: lines.slice(0, Math.min(lines.length, 10)).map((line, i) => ({
      line: i + 1,
      code: line,
      explanation: getLineExplanation(line, i),
    })),
  }
}

function getLineExplanation(line: string, index: number): string {
  const trimmed = line.trim()
  if (trimmed.startsWith('//') || trimmed.startsWith('#')) return 'Comment: ' + trimmed.slice(2).trim()
  if (trimmed.startsWith('import') || trimmed.startsWith('from')) return 'Import statement: brings in external dependencies'
  if (trimmed.startsWith('function') || trimmed.startsWith('def') || trimmed.startsWith('const') && trimmed.includes('=>')) return 'Function declaration: defines a reusable block of code'
  if (trimmed.startsWith('return')) return 'Return statement: exits the function with a value'
  if (trimmed.startsWith('const') || trimmed.startsWith('let') || trimmed.startsWith('var')) return 'Variable declaration: stores a value for later use'
  if (trimmed.includes('if') || trimmed.includes('else')) return 'Conditional statement: executes code based on a condition'
  if (trimmed.includes('for') || trimmed.includes('while')) return 'Loop: repeats code execution until a condition is met'
  if (!trimmed) return 'Empty line for readability'
  return `Line ${index + 1}: Core logic implementation`
}

